   write(new JSONObject().put("action","syncLibrary").put("version",14).put("phase","manifest").put("deviceId","article-peer-phone").put("supportsChunkedBodies",true).put("supportsArticleBatches",true).put("supportsChangeSequences",true).put("supportsMetadataOnlyArticles",true).put("requestPersistentSession",true).put("supportsPersistentSession",true).put("fullSnapshot",true).put("changeSeqRange",new JSONObject().put("fromExclusive",0).put("toInclusive",11)).put("articleManifest",new JSONArray().put(manifest)));
